/*
 * coll_names.h - a second (third) copy of the collision code under other names
 *
 * Force-included, with COLL_SUFFIX defined (-DCOLL_SUFFIX=_x87), when cm_load.c cm_test.c cm_trace.c cm_patch.c cm_polylib.c and
 * sv_world.c are compiled a further time: every global of those files gets the suffix, so the copies live side by side and the
 * host (host/coll.h) runs one of them. See third_party/README.md for why there is more than one.
 */
